// Menu inspection never writes or migrates a saved run.
export function menuRunSummary(raw){try{const run=JSON.parse(raw);if(!run||!Number.isInteger(run.round)||run.round<1)return null;if(run.modularVersion===1&&run.collection)return 'ROUND '+String(run.round).padStart(2,'0');if(!Array.isArray(run.owned)||!run.owned.length)return null;return 'ROUND '+String(run.round).padStart(2,'0');}catch{return null;}}
